import fs from "node:fs";
import path from "node:path";
import type { CategoryKey, ChannelKey, RoleKey } from "./types.js";

/**
 * Maps our stable blueprint keys ("moderator", "moderatorLog", ...) to the
 * real Discord snowflake IDs created for THIS guild. Generated by
 * `scripts/setup-server.ts --apply` and consumed at bot runtime so the rest
 * of the code never hardcodes an ID.
 */
export interface ServerMap {
  guildId: string;
  roles: Partial<Record<RoleKey, string>>;
  categories: Partial<Record<CategoryKey, string>>;
  channels: Partial<Record<ChannelKey, string>>;
  updatedAt: string;
}

const MAP_PATH = path.resolve(process.cwd(), "server-map.json");

export function loadServerMap(): ServerMap | null {
  if (!fs.existsSync(MAP_PATH)) return null;
  try {
    return JSON.parse(fs.readFileSync(MAP_PATH, "utf-8")) as ServerMap;
  } catch {
    return null;
  }
}

export function saveServerMap(map: ServerMap): void {
  fs.writeFileSync(MAP_PATH, JSON.stringify(map, null, 2) + "\n", "utf-8");
}

export function emptyServerMap(guildId: string): ServerMap {
  return { guildId, roles: {}, categories: {}, channels: {}, updatedAt: new Date().toISOString() };
}
